let S_LOADING=null,S_READY=0,S_DONE=0,S_TOTAL=0;
export function samplesReady(){return S_READY;}
// The share of the zones already settled (decoded or failed), for the loading cover (0.40): 0 before loading starts, 1 when there is
// nothing to decode (no audio decoding in this browser).
export function samplesLoaded(){return S_TOTAL?S_DONE/S_TOTAL:S_LOADING?1:0;}
function Sbytes(file){const b64=SAMPLE_EMBEDDED?.[file];if(b64){const s=atob(b64),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);return Promise.resolve(u.buffer);}
 return fetch('./assets/samples/'+file).then(r=>{if(!r.ok)throw new Error(file);return r.arrayBuffer();});}
function Sdecode(ctx,data){return new Promise((ok,fail)=>{const p=ctx.decodeAudioData(data,ok,fail);if(p&&p.then)p.then(ok,fail);});}
// Onset of a decoded note: the first millisecond louder than 36 dB below its peak.
export function sampleOnset(x,rate){const hop=Math.max(1,Math.round(rate*.001)),n=Math.ceil(x.length/hop),env=new Float32Array(n);let peak=0;
 for(let i=0;i<n;i++){let m=0;for(let j=i*hop,e=Math.min(x.length,j+hop);j<e;j++){const a=Math.abs(x[j]);if(a>m)m=a;}env[i]=m;if(m>peak)peak=m;}
 if(!peak)return 0;const thr=peak*10**(-36/20);for(let i=0;i<n;i++)if(env[i]>=thr)return Math.max(0,(i-2)*hop)/rate;return 0;}
// MP3 decoders that ignore the encoder's gapless information deliver 1105 samples of priming (some 1152 more): when a buffer comes back
// longer than the excerpt, the onset decides which of the two to skip, so attacks stay on the beat in every browser.
export function sampleShift(bufferDuration,duration,onset,mark){if(!(duration>0)||bufferDuration-duration<.01)return 0;const known=[1105/44100,2257/44100];
 return onset==null?known[0]:known.reduce((a,b)=>Math.abs(onset-mark-b)<Math.abs(onset-mark-a)?b:a);}
// Decodes every zone once per page (an offline context needs no user gesture). load(file) can supply the bytes instead (review tools).
// 0.40: the embedded bytes are read in slices of a few milliseconds, one task each, so the page keeps drawing (the loading cover moves
// on) while the browser decodes them in the background; before, the whole bank was read in one go and the page froze for about a second.
// At most `pool` zones are decoded at a time, so the finished ones come back spread out, not in one burst that stalls the drawing.
export function loadSamples({load=Sbytes,rate=44100,slice=8,pool=6}={}){if(S_LOADING)return S_LOADING;const AC=globalThis.OfflineAudioContext||globalThis.webkitOfflineAudioContext;
 if(!AC)return S_LOADING=Promise.resolve(0);let ctx;try{ctx=new AC(1,1,rate);}catch{return S_LOADING=Promise.resolve(0);}
 const zones=[...S_ZONES.values()].flat(),clock=()=>globalThis.performance?.now?.()??Date.now();S_TOTAL=zones.length;let busy=0,i=0,done=null,waiting=false;
 const job=z=>{let bytes;try{bytes=Promise.resolve(load(z.file));}catch(e){bytes=Promise.reject(e);}
  return bytes.then(data=>Sdecode(ctx,data)).then(buf=>{z.shift=sampleShift(buf.duration,z.duration,sampleOnset(buf.getChannelData(0),buf.sampleRate),z.mark);z.buffer=buf;S_READY++;}).catch(()=>{}).then(()=>{S_DONE++;busy--;
   if(S_DONE===zones.length)done(S_READY);else later();});};
 // one slice: new zones while there is room in the pool and time in the slice (always one, so a slice is never empty)
 const step=()=>{waiting=false;const t0=clock();while(i<zones.length&&busy<pool){busy++;job(zones[i++]);if(clock()-t0>=slice)break;}if(i<zones.length&&busy<pool)later();};
 const later=()=>{if(!waiting&&i<zones.length){waiting=true;setTimeout(step,0);}};
 return S_LOADING=new Promise(ok=>{done=ok;if(!zones.length){ok(0);return;}step();});}
// The decoded zone nearest to a note (the lower one on a tie), or, for unpitched instruments, one of the variant's recordings in turn.
const S_TURN=new Map();
export function sampleZone(inst,midi,variant){const zones=(S_ZONES.get(inst)||[]).filter(z=>z.buffer);if(!zones.length)return null;
 if(!SAMPLE_BANK[inst].pitched){const pool=zones.filter(z=>!variant||z.variant===variant);if(!pool.length&&SAMPLE_BANK[inst].strict)return null;const list=pool.length?pool:zones,k=(S_TURN.get(inst)||0)%list.length;S_TURN.set(inst,k+1);return list[k];}
 let best=zones[0];for(const z of zones)if(Math.abs(z.midi-midi)<Math.abs(best.midi-midi))best=z;return best;}
